import java.util.HashMap;
import java.util.Map;

class Rq {
    private final String actionName;
    private final Map<String, String> params = new HashMap<>();
    Rq(String request) {
        String[] parts = request.split("\\?", 2);
        actionName = parts[0];
        // 조건이 없으면 빈 Map을 유지해요.
        if (parts.length == 1 || parts[1].isEmpty()) return;
        for (String part : parts[1].split("&", -1)) {
            String[] pair = pair(part);
            // 같은 키가 두 번 오면 어느 값을 쓸지 몰래 고르지 않아요.
            if (params.containsKey(pair[0])) throw new IllegalArgumentException("duplicate");
            params.put(pair[0], pair[1]);
        }
    }
    private static String[] pair(String part) {
        // 값 안의 등호와 빈 값은 보존해요. 빈 키나 등호 없는 조각은 거절해요.
        String[] pair = part.split("=", 2);
        if (pair.length != 2 || pair[0].isBlank()) throw new IllegalArgumentException("parameter");
        return pair;
    }
    String getActionName() { return actionName; }
    // 키가 없을 때만 기본값을 써요. 있는 빈 값은 그대로 반환해요.
    String getParam(String name, String fallback) { return params.getOrDefault(name, fallback); }
    int getIntParam(String name, int fallback) {
        String value = params.get(name);
        return value == null ? fallback : Integer.parseInt(value);
    }
}

public class Main {
    public static void main(String[] args) {
        // 입력을 나누는 책임과 사용하는 책임을 구분해요.
        Rq rq = new Rq("update?id=2&text=hello");
        System.out.println(rq.getParam("id", "none"));
    }
}

